export function last<T>(items: readonly T[]): T | undefined {
  return items.length === 0 ? undefined : items[items.length - 1];
}

def parse_ratio(text: str) -> tuple[int, int]:
    parts = text.split(":")
    if len(parts) != 2 or any(not part or any(ch < "0" or ch > "9" for ch in part) for part in parts):
        raise ValueError("invalid ratio")
    numerator, denominator = map(int, parts)
    if denominator == 0:
        raise ValueError("zero denominator")
    return numerator, denominator

def transpose(rows):
    if not rows:
        return []
    width = len(rows[0])
    if any(len(row) != width for row in rows):
        raise ValueError("ragged rows")
    return [tuple(row[index] for row in rows) for index in range(width)]

def min_max(items):
    iterator = iter(items)
    try:
        minimum = maximum = next(iterator)
    except StopIteration:
        raise ValueError("empty input") from None
    for item in iterator:
        if item < minimum:
            minimum = item
        if item > maximum:
            maximum = item
    return minimum, maximum

def safe_lookup(values, index):
    if 0 <= index < len(values):
        return values[index]
    return None

export function compact<T>(items: readonly (T | null | undefined)[]): T[] {
  return items.filter((item): item is T => item !== null && item !== undefined);
}

function repeatText(text, count) {
  if (!Number.isSafeInteger(count) || count < 0) throw new RangeError("invalid count");
  return text.repeat(count);
}

export function isOneOf<T extends string>(value: string, allowed: readonly T[]): value is T {
  return allowed.some(option => option === value);
}

function clampNumber(value, low, high) {
  if (![value, low, high].every(Number.isFinite) || low > high) throw new RangeError("invalid bounds");
  return Math.min(high, Math.max(low, value));
}

static String maskTail(String text, int visible) {
    if (visible < 0) throw new IllegalArgumentException("negative visible");
    int hidden = Math.max(0, text.length() - visible);
    return "*".repeat(hidden) + text.substring(hidden);
}

static int[] reversedCopy(int[] values) {
    int[] result = new int[values.length];
    for (int i = 0; i < values.length; i++) {
        result[i] = values[values.length - 1 - i];
    }
    return result;
}

